import React from 'react';
import { RoomMember } from 'matrix-js-sdk/src/models/room-member';
import classNames from 'classnames';

import { getUserNameColorClass } from '../../../utils/FormattingUtils';
import UserIdentifier from "../../../customisations/UserIdentifier";

interface IProps {
    member?: RoomMember;
    fallbackName: string;
    onClick?(): void;
    colored?: boolean;
    emphasizeDisplayName?: boolean;
    element?: keyof React.ReactHTML;
}

export default class DisambiguatedProfile extends React.Component<IProps> {
    private onKeyDown = (event: React.KeyboardEvent<HTMLElement>): void => {
        if (!this.props.onClick || (event.key !== "Enter" && event.key !== " ")) return;

        event.preventDefault();
        this.props.onClick();
    };

    render() {
        const { fallbackName, member, colored, emphasizeDisplayName, onClick, element = "div" } = this.props;
        const rawDisplayName = member?.rawDisplayName || fallbackName;
        const mxid = member?.userId;

        let colorClass;
        if (colored) {
            colorClass = getUserNameColorClass(fallbackName);
        }

        let mxidElement;
        if (member?.disambiguate && mxid) {
            mxidElement = (
                <span className="mx_DisambiguatedProfile_mxid">
                    { UserIdentifier.getDisplayUserIdentifier(
                        mxid, { withDisplayName: true, roomId: member.roomId },
                    ) }
                </span>
            );
        }

        const displayNameClasses = classNames({
            "mx_DisambiguatedProfile_displayName": emphasizeDisplayName,
            [colorClass]: true,
        });

        const ProfileElement = element;

        return (
            <ProfileElement
                className="mx_DisambiguatedProfile"
                onClick={onClick}
                onKeyDown={this.onKeyDown}
                role={onClick ? "button" : undefined}
                tabIndex={onClick ? 0 : undefined}
            >
                <span className={displayNameClasses} dir="auto">
                    { rawDisplayName }
                </span>
                { mxidElement }
            </ProfileElement>
        );
    }
}
