import React from 'react';
import { MatrixEvent } from 'matrix-js-sdk/src/models/event';

import dis from '../../../dispatcher/dispatcher';
import { _t } from '../../../languageHandler';
import { RoomPermalinkCreator } from "../../../utils/permalinks/Permalinks";
import ReplyTile from './ReplyTile';
import RoomContext, { TimelineRenderingType } from '../../../contexts/RoomContext';
import SenderProfile from "../messages/SenderProfile";
import CancelButton from "../buttons/Cancel";

function cancelQuoting(context: TimelineRenderingType) {
    dis.dispatch({
        action: 'reply_to_event',
        event: null,
        context,
    });
}

interface IProps {
    permalinkCreator: RoomPermalinkCreator;
    replyToEvent: MatrixEvent;
}

export default class ReplyPreview extends React.Component<IProps> {
    public static contextType = RoomContext;

    public render(): JSX.Element {
        if (!this.props.replyToEvent) return null;

        return <div className="mx_ReplyPreview">
            <div className="mx_ReplyPreview_section">
                <div className="mx_ReplyPreview_header">
                    <span className="mx_ReplyPreview_header_text">
                        { _t("Replying to") }{ " " }
                        <SenderProfile
                            mxEvent={this.props.replyToEvent}
                            element="span"
                            showForEmotes={true}
                        />
                    </span>
                    <CancelButton
                        size="18"
                        aria-label={_t("Cancel replying to a message")}
                        onClick={() => cancelQuoting(this.context.timelineRenderingType)}
                    />
                </div>
                <ReplyTile
                    mxEvent={this.props.replyToEvent}
                    permalinkCreator={this.props.permalinkCreator}
                />
            </div>
        </div>;
    }
}

